pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(uint16 feeRate_, uint56 changeFee, uint128 vBase, uint128 vNft, address baseToken, address nft, bytes32 merkleRoot, bool useOracle, bool payRoyalties) public {

        bool ok;
        try c.initialize(baseToken, nft, vBase, vNft, changeFee, feeRate_, merkleRoot, useOracle, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false || c.feeRate() <= 5000);
    }
}
